"""Publish known build outputs without allowing COLLECT to clean the repository root."""

import hashlib
import json
import shutil
from pathlib import Path

ROOT = Path(__file__).resolve().parents[1]
STAGE = ROOT / "build/windows/stage/RadixScope"


def remove_previous_generated_notices() -> None:
    """Delete only verified assets generated by older RadixScope builds."""
    folder = ROOT / "_internal/licenses"
    inventory_file = folder / "inventory.json"
    notice_file = folder / "NOTICE.html"
    if not inventory_file.is_file() or not notice_file.is_file():
        return
    if "<h1>RadixScope: third-party notices</h1>" not in notice_file.read_text(
        encoding="utf-8"
    ):
        return
    inventory = json.loads(inventory_file.read_text(encoding="utf-8"))
    if not isinstance(inventory, dict) or not isinstance(inventory.get("notice_files"), list):
        return
    for filename in inventory["notice_files"]:
        if not isinstance(filename, str) or filename != Path(filename).name:
            continue
        source = folder / filename
        prefix = filename.split("-", 1)[0]
        if (
            not source.is_symlink()
            and source.is_file()
            and len(prefix) == 12
            and hashlib.sha256(source.read_bytes()).hexdigest().startswith(prefix)
        ):
            source.unlink()
    notice_file.unlink()
    inventory_file.unlink()
    if not any(folder.iterdir()):
        folder.rmdir()


def main() -> None:
    executable = STAGE / "RadixScope.exe"
    runtime = STAGE / "_internal"
    if not executable.is_file() or not runtime.is_dir():
        raise RuntimeError("incomplete Windows build")
    manifest = ROOT / "build/windows/published.json"
    previous = json.loads(manifest.read_text()) if manifest.exists() else {}
    if not isinstance(previous, dict) or any(
        not isinstance(key, str)
        or ".." in Path(key).parts
        or not (key == "RadixScope.exe" or key.startswith("_internal/"))
        for key in previous
    ):
        raise RuntimeError("invalid generated-output manifest")
    files = [executable, *[p for p in runtime.rglob("*") if p.is_file()]]
    for source in files:
        target = ROOT / source.relative_to(STAGE)
        relative = target.relative_to(ROOT).as_posix()
        if target.is_symlink() or not target.resolve().is_relative_to(ROOT.resolve()):
            raise RuntimeError("output path leaves the project root")
        if (
            target.exists()
            and hashlib.sha256(target.read_bytes()).hexdigest() != previous.get(relative)
            and target.read_bytes() != source.read_bytes()
        ):
            raise RuntimeError(f"Unmanaged output exists: {relative}; move it before building")
    old = ROOT / "dist/RadixScope/RadixScope.exe"
    if old.exists():
        import pefile

        pe = pefile.PE(str(old))
        names = [
            table.entries.get(b"ProductName")
            for groups in pe.FileInfo
            for group in groups
            if group.Key == b"StringFileInfo"
            for table in group.StringTable
        ]
        pe.close()
        if b"RadixScope" not in names or old.with_suffix(".exe.previous-build").exists():
            raise RuntimeError(
                "Move the old dist folder before building; it will not be overwritten"
            )
        old.rename(old.with_suffix(".exe.previous-build"))
    published = {}
    for source in files:
        relative = source.relative_to(STAGE)
        target = ROOT / relative
        target.parent.mkdir(parents=True, exist_ok=True)
        shutil.copy2(source, target)
        published[relative.as_posix()] = hashlib.sha256(source.read_bytes()).hexdigest()
    for relative, digest in previous.items():
        if not isinstance(relative, str) or not relative.startswith("_internal/"):
            continue
        path = (ROOT / relative).resolve()
        if (
            relative not in published
            and path.is_relative_to(ROOT)
            and path.is_file()
            and hashlib.sha256(path.read_bytes()).hexdigest() == digest
        ):
            path.unlink()
    remove_previous_generated_notices()
    manifest.write_text(json.dumps(published, indent=2), encoding="utf-8")


if __name__ == "__main__":
    main()
